import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"AI Data Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"ai/pipeline.md","filePath":"ai/pipeline.md"}`),a={name:`ai/pipeline.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="ai-data-pipeline" tabindex="-1">AI Data Pipeline <a class="header-anchor" href="#ai-data-pipeline" aria-label="Permalink to &quot;AI Data Pipeline&quot;">​</a></h1><p>TechyNews relies on a sophisticated AI data pipeline to automate the creation of high-quality, multi-lingual journalism. This pipeline handles everything from ingesting raw news signals to synthesizing deep-dive articles.</p><h2 id="the-content-lifecycle" tabindex="-1">The Content Lifecycle <a class="header-anchor" href="#the-content-lifecycle" aria-label="Permalink to &quot;The Content Lifecycle&quot;">​</a></h2><h3 id="_1-signal-ingestion" tabindex="-1">1. Signal Ingestion <a class="header-anchor" href="#_1-signal-ingestion" aria-label="Permalink to &quot;1. Signal Ingestion&quot;">​</a></h3><p>The process begins by aggregating raw information.</p><ul><li>The <code>NewsService</code> periodically polls RSS feeds from high-signal technology sources like TechCrunch, Hacker News, and The Verge.</li><li>Incoming items are parsed, sanitized, and deduplicated based on URLs and titles to ensure unique content.</li></ul><h3 id="_2-automated-synthesis-quality-v2-pipeline" tabindex="-1">2. Automated Synthesis (Quality v2 Pipeline) <a class="header-anchor" href="#_2-automated-synthesis-quality-v2-pipeline" aria-label="Permalink to &quot;2. Automated Synthesis (Quality v2 Pipeline)&quot;">​</a></h3><p>Once a critical mass of raw signals is collected, the synthesis phase begins:</p><ul><li><strong>Research Dossier (<code>ArticleResearchService</code>):</strong> Rather than writing from a single scraped page, the system compiles a multi-source research dossier. It cleans primary markdown (stripping GDPR banners, cookies, and navigation chrome), fetches corroborating sources via DuckDuckGo and Wikipedia fallbacks, and collects verified figure images.</li><li><strong>Fact Sheet Extraction (<code>GeminiService::buildFactSheet</code>):</strong> The AI extracts a strict factual ledger before drafting. It explicitly distinguishes who discovered the flaw from who detected in-the-wild exploitation or issued patches, records exact statistics with their precise scope (e.g. W3Techs survey scope), and identifies real affected organizations.</li><li><strong>Explanatory Drafting (<code>GeminiService::generateExploratoryArticle</code>):</strong> Models articles after top-tier tech journalism (Xataka, Ars Technica, Wired). Talks directly to the reader, uses narrative subheadings, embeds real figures with captions, provides actionable guidance (e.g. <code>php -v</code>, WAF rules), and completely bans preachy corporate sermonizing.</li><li><strong>Quality Audit (<code>ArticleQualityGate</code>):</strong> Enforces a strict filter against 40+ banned corporate fluff clichés (e.g., &quot;stark reminder&quot;, &quot;recordatorio contundente&quot;, &quot;enterprises must elevate security to a critical business function&quot;). If violations are detected, an automated AI editor pass rewrites the text substituting fluff with concrete facts.</li><li><strong>Storage:</strong> Stored directly in raw HTML format in the <code>content</code> column of the <code>articles</code> database table.</li></ul><h3 id="_3-metadata-generation" tabindex="-1">3. Metadata Generation <a class="header-anchor" href="#_3-metadata-generation" aria-label="Permalink to &quot;3. Metadata Generation&quot;">​</a></h3><p>In a post-processing pass, the AI extracts metadata from the generated article:</p><ul><li><strong>SEO Tags:</strong> Optimized meta titles and descriptions.</li><li><strong>Summaries:</strong> Short, engaging excerpts for the homepage grid.</li><li><strong>Reading Time:</strong> Estimated based on word count.</li></ul><h2 id="the-translation-engine" tabindex="-1">The Translation Engine <a class="header-anchor" href="#the-translation-engine" aria-label="Permalink to &quot;The Translation Engine&quot;">​</a></h2><p>TechyNews supports English (en), Spanish (es), and Portuguese (pt).</p><ul><li><strong>Native Localization (<code>GeminiService::translateArticle</code>):</strong> Rather than literal machine translation, the model acts as a native localization editor for leading Spanish tech publications (Xataka, Gizmodo en Español). It forbids literal calques (&quot;en un desarrollo inquietante&quot;, &quot;recordatorio contundente&quot;, &quot;las empresas deben&quot;), preserves all HTML tags and figures, and adapts phrasing for natural flow.</li><li><strong>Caching:</strong> Translated content is stored in the <code>translations</code> JSON column of the database.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};